import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'sop-store',
  description:
    "Read and update the SOP library: its index (sops/index.json) and one markdown file per procedure under sops/. action:'status' for what is flagged, past its review date or due soon; 'find' to answer a 'how do I…' question from the written steps; 'save' to write or rewrite a procedure (an existing id or title is updated, never duplicated); 'review' when someone checked one and it is still right; 'flag' when one no longer matches the work; 'retire' when it is no longer used; 'list' for the whole library by area.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'find', 'save', 'review', 'flag', 'retire', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Procedure id, e.g. 'sop-3'." },
    title: {
      type: 'string',
      description: "The procedure's name, e.g. 'Closing the espresso machine'. Also finds it when no id is given.",
    },
    area: { type: 'string', description: 'opening, closing, customers, kitchen, cleaning, safety, money, stock, people, equipment, office, or other.' },
    owner: { type: 'string', description: 'Who keeps it right: usually the person who does the job.' },
    steps: {
      type: 'string',
      description: 'The procedure in markdown: numbered steps, one action each, with any warnings. Replaces the written steps.',
    },
    summary: { type: 'string', description: 'One line on when to use it.' },
    reviewEveryDays: { type: 'number', description: 'How often it should be checked, in days (default 180).' },
    reviewedAt: {
      type: 'string',
      description: 'When it was last checked, YYYY-MM-DD, if not today (for procedures filed from an existing binder).',
    },
    note: { type: 'string', description: 'What changed or who checked it, in the words used.' },
    query: { type: 'string', description: "For find: the question as asked, e.g. 'how do I close the espresso machine'." },
  },
  outputs: {
    outOfDate: { type: 'number', description: 'Procedures flagged for an update or past their review date.' },
    dueSoon: { type: 'number', description: 'Procedures due for review within 30 days.' },
    procedures: { type: 'number', description: 'Procedures in use (not retired).' },
    summary: { type: 'string', description: 'The library picture, the answer to a find, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── sop-rules-start ──
// Pure derivations: when each procedure is next due for review, which ones
// are out of date, the "how do I…" match score, and the lines the crew reads.
// Kept self-contained between these sentinels so unit tests execute the
// shipped bytes.
var DAY_MS = 86400000;
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTH_KEYS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function noon(day) {
  return new Date(String(day).slice(0, 10) + 'T12:00:00');
}
function addDays(day, n) {
  var d = noon(day);
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function addMonths(day, months) {
  var d = noon(day);
  var date = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  // The 31st rolls to the last day of a shorter month, not into the next one.
  d.setDate(Math.min(date, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function dayName(day) {
  return WEEKDAYS[noon(day).getDay()];
}
function parseDay(text, nowMs, direction) {
  var raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  var iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:t.*)?$/);
  if (iso) return iso[1] + '-' + pad(Number(iso[2])) + '-' + pad(Number(iso[3]));
  var today = localDay(nowMs);
  if (raw === 'today' || raw === 'now') return today;
  if (raw === 'tomorrow') return addDays(today, 1);
  if (raw === 'yesterday') return addDays(today, -1);
  var rel = raw.match(/^(?:in )?(\d{1,3}) (day|days|week|weeks)( ago| from now)?$/);
  if (rel) {
    var n = Number(rel[1]) * (rel[2].charAt(0) === 'w' ? 7 : 1);
    return addDays(today, rel[3] === ' ago' ? -n : n);
  }
  var wd = raw.match(/^(this |next |last |on |coming )?(sun|mon|tue|wed|thu|fri|sat)[a-z]*$/);
  if (wd) {
    var target = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'].indexOf(wd[2]);
    var now = noon(today).getDay();
    if (direction === 'past' || wd[1] === 'last ') {
      var back = (now - target + 7) % 7;
      return addDays(today, -(wd[1] === 'last ' && back === 0 ? 7 : back));
    }
    if (wd[1] === 'this ') return addDays(today, (target - now + 7) % 7);
    return addDays(today, ((target - now + 6) % 7) + 1);
  }
  var md = raw.match(/^(?:[a-z]+day )?([a-z]{3,9}) (\d{1,2})(?:st|nd|rd|th)?(?: (\d{4}))?$/);
  var dm = raw.match(/^(?:[a-z]+day )?(\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]{3,9})(?: (\d{4}))?$/);
  var parts = md ? { month: md[1], date: md[2], year: md[3] } : dm ? { month: dm[2], date: dm[1], year: dm[3] } : null;
  if (parts) {
    var m = MONTH_KEYS.indexOf(parts.month.slice(0, 3));
    if (m < 0) return null;
    var date = Number(parts.date);
    if (date < 1 || date > 31) return null;
    if (parts.year) return parts.year + '-' + pad(m + 1) + '-' + pad(date);
    var year = noon(today).getFullYear();
    var guess = year + '-' + pad(m + 1) + '-' + pad(date);
    var d = daysLeft(guess, nowMs);
    if (direction === 'past' && d > 0) guess = year - 1 + guess.slice(4);
    if (direction !== 'past' && d < 0) guess = year + 1 + guess.slice(4);
    return guess;
  }
  return null;
}
function matches(records, text, labelOf) {
  var wanted = String(text == null ? '' : text).trim().toLowerCase().replace(/['\u2019]s\b/g, '').replace(/\s+/g, ' ');
  if (!wanted) return [];
  var tiers = [
    function (r) { return String(r.id).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) === 0; },
    function (r) { return (' ' + labelOf(r).toLowerCase() + ' ').indexOf(' ' + wanted + ' ') >= 0; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) >= 0; },
    function (r) { var l = labelOf(r).toLowerCase(); return l.length >= 3 && wanted.indexOf(l) >= 0; },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hit = records.filter(tiers[i]);
    if (hit.length) return hit;
  }
  return [];
}
function describe(records, labelOf) {
  return records.map(function (r) { return r.id + ' ' + labelOf(r); }).join(', ');
}
function splitList(text) {
  var raw = String(text == null ? '' : text).trim();
  if (/^\[/.test(raw)) {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(function (s) { return String(s).trim(); }).filter(Boolean);
    } catch (e) {
      // Not JSON after all; split it as text.
    }
  }
  return raw
    .split(/\s*[,;\n]+\s*/)
    .map(function (s) { return s.replace(/^(and|or|plus)\s+/i, '').replace(/[.\s]+$/, '').trim(); })
    .filter(Boolean);
}
var AREAS = ["opening","closing","customers","kitchen","cleaning","safety","money","stock","people","equipment","office","other"];
var DEFAULT_REVIEW_DAYS = 180;
var SOON_DAYS = 30;
var STOP = ['how', 'do', 'does', 'did', 'done', 'we', 'you', 'they', 'an', 'the', 'to', 'of', 'in', 'on', 'at', 'for', 'with', 'and', 'or', 'is', 'are', 'was', 'what', 'when', 'where', 'who', 'which', 'should', 'can', 'could', 'our', 'my', 'your', 'it', 'its', 'this', 'that', 'there', 'about', 'get', 'me', 'us', 'be', 'have', 'has', 'if', 'then', 'up', 'out', 'into', 'again', 'any', 'some', 'need', 'procedure', 'procedures', 'sop', 'steps', 'step', 'way', 'right', 'properly', 'please', 'tell', 'show'];

// "closing", "closed" and "close" all become "clos"; "machines" and "machine" become "machin".
function stem(word) {
  var w = word;
  if (w.length > 5 && /ing$/.test(w)) w = w.slice(0, -3);
  else if (w.length > 4 && /ed$/.test(w)) w = w.slice(0, -2);
  else if (w.length > 4 && /es$/.test(w)) w = w.slice(0, -2);
  else if (w.length > 3 && /s$/.test(w) && !/ss$/.test(w)) w = w.slice(0, -1);
  if (w.length > 4 && /e$/.test(w)) w = w.slice(0, -1);
  return w;
}
function tokens(text) {
  var seen = [];
  String(text == null ? '' : text).toLowerCase().split(/[^a-z0-9]+/).forEach(function (w) {
    if (w.length < 2 || STOP.indexOf(w) >= 0) return;
    var s = stem(w);
    if (seen.indexOf(s) < 0) seen.push(s);
  });
  return seen;
}
// Title words count three times, area and summary twice, the steps once.
function score(record, body, query) {
  var q = tokens(query);
  if (!q.length) return 0;
  var f = record.fields || {};
  var title = tokens(f.title), meta = tokens((f.area || '') + ' ' + (f.summary || '')), text = tokens(body);
  var total = 0, hit = 0;
  q.forEach(function (w) {
    var s = title.indexOf(w) >= 0 ? 3 : meta.indexOf(w) >= 0 ? 2 : text.indexOf(w) >= 0 ? 1 : 0;
    if (s) hit += 1;
    total += s;
  });
  return hit ? total + hit / q.length : 0;
}
function reviewDays(f) {
  var n = Number(f.reviewEveryDays);
  return n > 0 ? Math.round(n) : DEFAULT_REVIEW_DAYS;
}
function nextReview(f) {
  return f.lastReviewedAt ? addDays(String(f.lastReviewedAt).slice(0, 10), reviewDays(f)) : null;
}
// retired, flagged (needs-update), draft, unreviewed, stale (past its review date), soon, ok.
function reviewState(record, nowMs) {
  if (record.status === 'retired') return 'retired';
  if (record.status === 'needs-update') return 'flagged';
  if (record.status === 'draft') return 'draft';
  var f = record.fields || {};
  if (!f.lastReviewedAt) return 'unreviewed';
  var d = daysLeft(nextReview(f), nowMs);
  return d < 0 ? 'stale' : d <= SOON_DAYS ? 'soon' : 'ok';
}
function flagNote(record) {
  var history = record.history || [];
  for (var i = history.length - 1; i >= 0; i--) {
    if (history[i].to === 'needs-update' && history[i].note) return history[i].note;
  }
  return '';
}
function ago(days) {
  return days === 0 ? 'today' : days === 1 ? 'yesterday' : days + ' days ago';
}
function line(record, nowMs) {
  var f = record.fields || {};
  var state = reviewState(record, nowMs);
  var next = nextReview(f);
  var reviewed = f.lastReviewedAt ? 'last reviewed ' + f.lastReviewedAt + ' (' + ago(-daysLeft(f.lastReviewedAt, nowMs)) + ')' : 'never reviewed';
  var what =
    state === 'flagged' ? 'flagged for an update' + (flagNote(record) ? ': "' + flagNote(record) + '"' : '') + '; ' + reviewed
    : state === 'draft' ? 'draft, no steps written yet'
    : state === 'retired' ? 'retired'
    : state === 'unreviewed' ? 'never reviewed'
    : state === 'stale' ? reviewed + '; review overdue by ' + -daysLeft(next, nowMs) + ' days (every ' + reviewDays(f) + ' days)'
    : state === 'soon' ? reviewed + '; review due in ' + daysLeft(next, nowMs) + ' days'
    : reviewed + '; next review ' + next;
  return f.title + ' (' + record.id + ', ' + (f.area || 'other') + ', owner ' + (f.owner || 'none yet') + '): ' + what;
}
// Known-wrong first, then the most overdue, then reviews coming due.
function urgency(record, nowMs) {
  var state = reviewState(record, nowMs);
  if (state === 'flagged') return -1000000;
  if (state === 'unreviewed') return -500000;
  var next = nextReview(record.fields || {});
  return next ? daysLeft(next, nowMs) : 0;
}
function picture(records, nowMs) {
  var live = records.filter(function (r) { return r.status !== 'retired'; });
  var states = live.map(function (r) { return reviewState(r, nowMs); });
  var pick = function (names) { return live.filter(function (r, i) { return names.indexOf(states[i]) >= 0; }); };
  var outOfDate = pick(['flagged', 'unreviewed', 'stale']);
  var soon = pick(['soon']);
  var drafts = pick(['draft']);
  var areas = [];
  live.forEach(function (r) { var a = (r.fields && r.fields.area) || 'other'; if (areas.indexOf(a) < 0) areas.push(a); });
  areas.sort(function (a, b) { return AREAS.indexOf(a) - AREAS.indexOf(b); });
  var parts = [
    live.length + (live.length === 1 ? ' procedure' : ' procedures') + ' in ' + areas.length + (areas.length === 1 ? ' area' : ' areas') + '; ' +
      outOfDate.length + ' out of date, ' + soon.length + ' due for review within ' + SOON_DAYS + ' days.',
  ];
  // One list, most urgent first: a model asked what is out of date reads one list, not side lists.
  var attention = outOfDate.concat(soon).sort(function (a, b) { return urgency(a, nowMs) - urgency(b, nowMs); });
  parts.push(
    attention.length
      ? 'Out of date or due for review, most urgent first: ' + attention.map(function (r) { return line(r, nowMs); }).join(' | ') + '.'
      : live.length ? 'Every procedure is current.' : 'The library is empty.',
  );
  if (drafts.length) parts.push('Drafts with no steps yet: ' + drafts.map(function (r) { return r.fields.title + ' (' + r.id + ')'; }).join(', ') + '.');
  if (areas.length) {
    parts.push(
      'By area: ' + areas.map(function (a) {
        return a + ': ' + live.filter(function (r) { return ((r.fields && r.fields.area) || 'other') === a; }).map(function (r) { return r.fields.title + ' (' + r.id + ')'; }).join(', ');
      }).join('; ') + '.',
    );
    // The steps live in the files: a model answering from this summary alone would invent them.
    parts.push("Steps are not in this summary; for a 'how do I…' question, call find_procedure with the question and answer from its steps.");
  }
  return { outOfDate: outOfDate.length, dueSoon: soon.length, procedures: live.length, summary: parts.join(' ') };
}
function procedureLabel(r) {
  return String((r.fields && r.fields.title) || '');
}
// By id or title first, then every telling word of the request.
function findProcedures(records, text) {
  var hit = matches(records, text, procedureLabel);
  if (hit.length) return hit;
  var want = tokens(text);
  if (!want.length) return [];
  return records.filter(function (r) {
    var have = tokens(procedureLabel(r));
    return want.every(function (w) { return have.indexOf(w) >= 0; });
  });
}
function slugOf(title) {
  var slug = String(title).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).replace(/-+$/, '');
  return slug || 'procedure';
}
// The title is the file's one heading; a pasted copy of it is dropped.
function bodyOf(title, steps) {
  var text = String(steps).replace(/\r\n/g, '\n').trim().replace(/^#\s+[^\n]*\n+/, '');
  return '# ' + title + '\n\n' + text + '\n';
}
// ── sop-rules-end ──

const library = rosterStore(gezel.fs, 'sops/index.json', {
  stages: ['draft', 'current', 'needs-update', 'retired'],
  idPrefix: 'sop',
});
type Procedure = Awaited<ReturnType<typeof library.list>>[number];

const now = Date.now();
const today = localDay(now);
let note = '';
let answer = '';

function clip(text: string, max: number): string {
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
}
function known(all: Procedure[]): string {
  return describe(all, procedureLabel) || 'none yet';
}
async function readBody(file: unknown): Promise<string> {
  if (typeof file !== 'string' || !file) return '';
  try {
    return await gezel.fs.read(file);
  } catch {
    return '';
  }
}

async function resolveProcedure(): Promise<Procedure> {
  const all = await library.list();
  const text = input.id || input.title;
  if (!text) throw new Error("Pass 'id' (e.g. 'sop-3') or the procedure's 'title'. Procedures: " + known(all) + '.');
  const hits = findProcedures(all, text);
  if (hits.length === 1) return hits[0]!;
  if (hits.length > 1) throw new Error("More than one procedure matches '" + text + "': " + describe(hits, procedureLabel) + '. Pass id.');
  throw new Error("No procedure matches '" + text + "'. Procedures: " + known(all) + '.');
}

if (input.action === 'save') {
  const all = await library.list();
  const wanted = String(input.title ?? '').trim().toLowerCase();
  let existing = input.id
    ? all.find((r) => r.id === input.id)
    : all.find((r) => String(r.fields.title ?? '').toLowerCase() === wanted);
  if (input.id && !existing) throw new Error('No procedure ' + input.id + '. Procedures: ' + known(all) + '.');
  if (!existing && !wanted) throw new Error("save needs 'title'.");
  const steps = typeof input.steps === 'string' && input.steps.trim() ? input.steps : '';
  // A reworded title ("Espresso machine closing") is the same procedure.
  if (!existing) {
    const words = tokens(input.title).sort().join(' ');
    const same = all.filter((r) => words && tokens(r.fields.title).sort().join(' ') === words);
    if (same.length === 1) existing = same[0];
  }
  // A loose title names an existing procedure when the call only changes its details. New steps
  // never overwrite a loosely matched one: the caller names it by id or gives the new one its own title.
  if (!existing) {
    const loose = findProcedures(all, input.title).filter((r) => r.status !== 'retired');
    if (loose.length > 1) {
      throw new Error("More than one procedure matches '" + input.title + "': " + describe(loose, procedureLabel) + '. Pass id to change one, or give a new procedure its own full title.');
    }
    if (loose.length === 1 && !steps) existing = loose[0];
    else if (loose.length === 1) {
      throw new Error("'" + input.title + "' looks like " + String(loose[0]!.fields.title) + ' (' + loose[0]!.id + "). To rewrite it, pass id '" + loose[0]!.id + "'; to add a separate procedure, give it its own full title.");
    }
  }
  const area = AREAS.indexOf(String(input.area ?? '').toLowerCase()) >= 0 ? String(input.area).toLowerCase() : undefined;
  let reviewedAt: string | null = null;
  if (input.reviewedAt) {
    reviewedAt = parseDay(input.reviewedAt, now, 'past');
    if (!reviewedAt) throw new Error("reviewedAt must be a date, e.g. '2026-03-14'.");
    if (daysLeft(reviewedAt, now) > 0) reviewedAt = today;
  }
  const fields: Record<string, unknown> = {
    ...(area ? { area } : {}),
    ...(input.owner ? { owner: input.owner.trim() } : {}),
    ...(input.summary ? { summary: input.summary.trim() } : {}),
    ...(typeof input.reviewEveryDays === 'number' && input.reviewEveryDays > 0 ? { reviewEveryDays: Math.round(input.reviewEveryDays) } : {}),
  };
  if (existing) {
    const title = input.id && input.title && input.title.trim() ? input.title.trim() : String(existing.fields.title);
    if (title !== existing.fields.title) fields.title = title;
    if (steps) {
      await gezel.fs.write(String(existing.fields.file), bodyOf(title, steps));
      fields.lastReviewedAt = reviewedAt ?? today;
    } else if (reviewedAt) {
      fields.lastReviewedAt = reviewedAt;
    }
    await library.update(existing.id, { fields, ...(steps ? { note: input.note ?? 'Steps rewritten.' } : input.note ? { note: input.note } : {}) });
    if (steps && existing.status !== 'current') await library.transition(existing.id, 'current', { note: 'Steps rewritten.' });
    note = 'Updated ' + title + (steps ? ' with new steps' : '') + '.';
  } else {
    const title = String(input.title).trim();
    const taken = all.map((r) => String(r.fields.file ?? ''));
    const slug = slugOf(title);
    let file = 'sops/' + slug + '.md';
    for (let n = 2; taken.indexOf(file) >= 0; n++) file = 'sops/' + slug + '-' + n + '.md';
    await gezel.fs.write(file, bodyOf(title, steps || '_No steps yet. Ask the person who does this job to walk through it once, and write down each action in order._'));
    const record = await library.add({
      status: steps ? 'current' : 'draft',
      fields: { title, area: area ?? 'other', file, ...fields, ...(steps ? { lastReviewedAt: reviewedAt ?? today } : {}) },
    });
    note = 'Added ' + record.id + ' ' + title + ' at ' + file + (steps ? '' : ' as a draft') + '.';
  }
} else if (input.action === 'find') {
  const query = String(input.query ?? input.title ?? '').trim();
  if (!query) throw new Error("find needs 'query': the question as asked.");
  const live = (await library.list()).filter((r) => r.status !== 'retired');
  const scored: Array<{ r: Procedure; body: string; s: number }> = [];
  for (const r of live) {
    const body = await readBody(r.fields.file);
    const s = score(r, body, query);
    if (s > 0) scored.push({ r, body, s });
  }
  scored.sort((a, b) => b.s - a.s);
  const best = scored[0];
  if (!best) {
    answer = "No procedure in the library matches '" + query + "'. Say so plainly, and offer to write one down with the person who does that job.";
  } else {
    const state = reviewState(best.r, now);
    answer =
      "Best match for '" + query + "': " + line(best.r, now) + '. File ' + String(best.r.fields.file) + '.\n\n' +
      clip(best.body.trim() || '(The file is empty.)', 4000) +
      (state === 'stale' || state === 'flagged' || state === 'unreviewed' ? '\n\nThis procedure is out of date; say so when you answer, and suggest the owner checks it.' : '') +
      (state === 'draft' ? '\n\nThis is a draft with no steps yet; say so rather than inventing steps.' : '') +
      (scored.length > 1 ? '\n\nAlso related: ' + scored.slice(1, 4).map((x) => String(x.r.fields.title) + ' (' + x.r.id + ')').join(', ') + '.' : '');
  }
} else if (input.action === 'review') {
  const r = await resolveProcedure();
  if (r.status === 'retired') throw new Error(String(r.fields.title) + ' is retired; save it again with steps to bring it back.');
  if (r.status === 'draft') throw new Error(String(r.fields.title) + ' is a draft with no steps yet; save its steps first.');
  await library.update(r.id, { fields: { lastReviewedAt: today }, note: input.note ?? 'Reviewed; still right.' });
  if (r.status === 'needs-update') await library.transition(r.id, 'current', { note: 'Reviewed; still right.' });
  note = String(r.fields.title) + ' marked reviewed today; next review ' + addDays(today, reviewDays(r.fields)) + '.';
} else if (input.action === 'flag') {
  if (!input.note || !input.note.trim()) throw new Error("flag needs 'note': what changed or what is wrong, in the person's words.");
  const r = await resolveProcedure();
  await library.transition(r.id, 'needs-update', { note: input.note.trim() });
  note = String(r.fields.title) + ' flagged for an update: ' + input.note.trim().replace(/[.\s]+$/, '') + '.';
} else if (input.action === 'retire') {
  const r = await resolveProcedure();
  await library.transition(r.id, 'retired', { note: input.note ?? 'Retired.' });
  note = String(r.fields.title) + ' retired; its file stays at ' + String(r.fields.file) + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, find, save, review, flag, retire, or list.");
}

const records = await library.list();
const shelf = picture(records, now);
const listing = () =>
  records
    .slice()
    .sort((a, b) => AREAS.indexOf(String(a.fields.area)) - AREAS.indexOf(String(b.fields.area)) || String(a.fields.title).localeCompare(String(b.fields.title)))
    .map((r) => '[' + r.status + '] ' + line(r, now) + '; file ' + String(r.fields.file))
    .join('\n') || 'The library is empty.';

gezel.output({
  outOfDate: shelf.outOfDate,
  dueSoon: shelf.dueSoon,
  procedures: shelf.procedures,
  summary: input.action === 'list' ? listing() : input.action === 'find' ? answer : (note ? note + ' ' : '') + shelf.summary,
});

